using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long s;
    cin >> n >> s;
    vector<long long> arr(n);
    for (int i = 0; i < n; i++) cin >> arr[i];

    vector<char> seen(n + 1, 0);
    seen[s] = 1;
    vector<long long> stack = {s};
    bool found = false;
    while (!stack.empty()) {
        long long i = stack.back();
        stack.pop_back();
        if (arr[i - 1] == 0) {
            found = true;
            break;
        }
        long long targets[2] = {i + arr[i - 1], i - arr[i - 1]};
        for (long long j : targets) {
            if (j >= 1 && j <= n && !seen[j]) {
                seen[j] = 1;
                stack.push_back(j);
            }
        }
    }
    cout << (found ? "yes" : "no") << "\n";

    return 0;
}

