import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long s = Long.parseLong(next());
        long[] arr = new long[(int) n];
        for (int i = 0; i < arr.length; i++) arr[i] = Long.parseLong(next());

        boolean[] seen = new boolean[(int) n + 1];
        seen[(int) s] = true;
        ArrayList<Long> stack = new ArrayList<>();
        stack.add(s);
        boolean found = false;
        while (!stack.isEmpty()) {
            long i = stack.remove(stack.size() - 1);
            if (arr[(int) i - 1] == 0) {
                found = true;
                break;
            }
            long[] targets = {i + arr[(int) i - 1], i - arr[(int) i - 1]};
            for (long j : targets) {
                if (j >= 1 && j <= n && !seen[(int) j]) {
                    seen[(int) j] = true;
                    stack.add(j);
                }
            }
        }
        System.out.println(found ? "yes" : "no");
    }
}
